def transform(grid):
 h=len(grid); w=len(grid[0]); out=[[5 if v==5 else 0 for v in row] for row in grid]; seen=set(); regions=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==5 or (r,c) in seen: continue
   stack=[(r,c)]; seen.add((r,c)); cells=[]; edge=False
   while stack:
    y,x=stack.pop(); cells.append((y,x))
    if y in (0,h-1) or x in (0,w-1): edge=True
    for a,b in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
     if 0<=a<h and 0<=b<w and grid[a][b]!=5 and (a,b) not in seen:
      seen.add((a,b)); stack.append((a,b))
   if not edge: regions.append(cells)
 regions.sort(key=len)
 for i,cells in enumerate(regions):
  color=3 if i==0 else (4 if i==len(regions)-1 else 2)
  for r,c in cells: out[r][c]=color
 return out

